const referenceLayoutJs = String.raw`
(function(){
  function applyChessReferenceLayout(){
    const layout=document.querySelector('body.chess-console .layout:not(.game-focus)');
    if(!layout||layout.dataset.referenceLayout==='yes')return;
    const boardarea=layout.querySelector('.boardarea');
    const sidebar=layout.querySelector(':scope > .sidebar');
    const arena=boardarea?.querySelector('.arena');
    const dock=arena?.querySelector('.side-dock');
    if(!boardarea||!sidebar||!arena||!dock)return;
    const heading=sidebar.querySelector('.gomoku-heading');
    if(heading){
      const headingSlot=document.createElement('div');
      headingSlot.className='chess-reference-heading';
      headingSlot.appendChild(heading);
      boardarea.insertBefore(headingSlot,boardarea.firstChild);
    }
    boardarea.appendChild(dock);
    dock.insertBefore(sidebar,dock.firstChild);
    const players=boardarea.querySelector(':scope > .players');
    if(players)dock.insertBefore(players,sidebar.nextSibling);
    const restart=sidebar.querySelector('#restart');
    const invite=dock.querySelector('#invite-friend');
    if(restart&&invite){
      const actions=document.createElement('div');
      actions.className='chess-reference-actions';
      restart.parentElement.insertBefore(actions,restart);
      actions.appendChild(restart);
      const button=document.createElement('button');
      button.type='button';button.className='chess-reference-invite';
      button.textContent='♙ Zaproś znajomego';
      button.addEventListener('click',()=>invite.click());
      actions.appendChild(button);
    }
    layout.dataset.referenceLayout='yes';
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',applyChessReferenceLayout,{once:true});
  else applyChessReferenceLayout();
})();
`;
export function serveChessConsole(req,res,url){if(req.method!=='GET')return false;const path=url.pathname.replace(/\/+$/,'')||'/';const asset={'/konto/szachy':['text/html; charset=utf-8',html],'/konto/szachy/styl.css':['text/css; charset=utf-8',css+referenceLayoutCss],'/konto/szachy/app.js':['application/javascript; charset=utf-8',js+referenceLayoutJs],'/konto/szachy/rules.mjs':['application/javascript; charset=utf-8',rulesSource],'/konto/szachy/pieces.mjs':['application/javascript; charset=utf-8',chessPiecesSource],'/konto/szachy/computer.mjs':['application/javascript; charset=utf-8',computerSource],'/konto/szachy/realtime-client.mjs':['application/javascript; charset=utf-8',realtimeClientSource],'/konto/szachy/invitations.css':['text/css; charset=utf-8',invitationCss],'/konto/szachy/invitations.js':['application/javascript; charset=utf-8',invitationJs]}[path];if(!asset)return false;res.writeHead(200,{...headers,'Content-Type':asset[0],'Content-Length':Buffer.byteLength(asset[1])});res.end(asset[1]);return true;}
